const lin = (x, k) => (Math.abs(x) < 1e-7 ? k : x / (1 - Math.exp(-x / k)));
const an = v => 0.01 * lin(v + 55, 10), bn = v => 0.125 * Math.exp(-(v + 65) / 80);
const am = v => 0.1 * lin(v + 40, 10),  bm = v => 4 * Math.exp(-(v + 65) / 18);
const ah = v => 0.07 * Math.exp(-(v + 65) / 20), bh = v => 1 / (1 + Math.exp(-(v + 35) / 10));

function hhStep(s, I, dt) {   // s = { v, m, h, n }, dt about 0.01 ms
  const iNa = 120 * s.m ** 3 * s.h * (s.v - 50);
  const iK = 36 * s.n ** 4 * (s.v + 77);
  const iL = 0.3 * (s.v + 54.387);
  s.v += dt * (I - iNa - iK - iL);
  s.m += dt * (am(s.v) * (1 - s.m) - bm(s.v) * s.m);
  s.h += dt * (ah(s.v) * (1 - s.h) - bh(s.v) * s.h);
  s.n += dt * (an(s.v) * (1 - s.n) - bn(s.v) * s.n);
}
